require __DIR__.'/config.php'; require __DIR__.'/database_upgrade.php'; try{$pdo=db();apply_database_upgrade($pdo);}catch(Throwable $e){exit('Directory unavailable.');}$page=$_GET['page']??'home';
function go(string $url):never{header('Location: '.$url);exit;} function cats(PDO $p):array{return $p->query('SELECT * FROM categories WHERE active=1 ORDER BY name')->fetchAll();} function services(PDO $p,int $id):array{$q=$p->prepare('SELECT bs.*,s.name FROM business_services bs JOIN services s ON s.id=bs.service_id WHERE bs.business_id=?');$q->execute([$id]);return $q->fetchAll();}
function list_businesses(PDO $p):array{$w=["b.status='approved'"];$v=[];$text=trim($_GET['q']??'');if($text!==''){$w[]='(b.name LIKE ? OR b.description LIKE ? OR EXISTS(SELECT 1 FROM business_services bs JOIN services s ON s.id=bs.service_id WHERE bs.business_id=b.id AND s.name LIKE ?))';array_push($v,"%$text%","%$text%","%$text%");}if(($x=(int)($_GET['category']??0))){$w[]='b.category_id=?';$v[]=$x;}if(($x=trim($_GET['area']??''))!==''){$w[]='(b.barangay LIKE ? OR b.district LIKE ? OR b.city LIKE ?)';array_push($v,"%$x%","%$x%","%$x%");}if(($_GET['verified']??'')==='1')$w[]='b.is_verified=1';if(($_GET['open']??'')==='1')$w[]='EXISTS(SELECT 1 FROM business_hours h WHERE h.business_id=b.id AND h.day_of_week='.date('w').' AND h.is_closed=0 AND h.opens<=CURRENT_TIME() AND h.closes>CURRENT_TIME())';if(($_GET['contact']??'')==='1')$w[]="b.contact_phone<>''";if(($_GET['map']??'')==='1')$w[]='b.latitude IS NOT NULL AND b.longitude IS NOT NULL';if(($_GET['services']??'')==='1')$w[]='EXISTS(SELECT 1 FROM business_services bs WHERE bs.business_id=b.id)';if(($x=(int)($_GET['rating']??0))>0){$w[]='(SELECT COALESCE(AVG(rr.rating),0) FROM reviews rr WHERE rr.business_id=b.id AND rr.status="visible")>=?';$v[]=$x;}if(($min=filter_input(INPUT_GET,'price_min',FILTER_VALIDATE_FLOAT))!==false&&$min!==null){$w[]='EXISTS(SELECT 1 FROM business_services bs WHERE bs.business_id=b.id AND bs.price>=?)';$v[]=$min;}if(($max=filter_input(INPUT_GET,'price_max',FILTER_VALIDATE_FLOAT))!==false&&$max!==null){$w[]='EXISTS(SELECT 1 FROM business_services bs WHERE bs.business_id=b.id AND bs.price<=?)';$v[]=$max;}$lat=filter_input(INPUT_GET,'lat',FILTER_VALIDATE_FLOAT);$lng=filter_input(INPUT_GET,'lng',FILTER_VALIDATE_FLOAT);$distance='NULL distance_km';if($lat!==false&&$lat!==null&&$lng!==false&&$lng!==null&&abs($lat)<=90&&abs($lng)<=180){$distance='(6371*ACOS(LEAST(1,COS(RADIANS(?))*COS(RADIANS(b.latitude))*COS(RADIANS(b.longitude)-RADIANS(?))+SIN(RADIANS(?))*SIN(RADIANS(b.latitude))))) distance_km';array_unshift($v,$lat,$lng,$lat);}$sort=$_GET['sort']??'relevance';$order=['rating'=>'rating DESC,reviews DESC','reviews'=>'reviews DESC,rating DESC','favorites'=>'favorites DESC,rating DESC','newest'=>'b.created_at DESC','name_az'=>'b.name ASC','name_za'=>'b.name DESC','nearest'=>'distance_km IS NULL,distance_km ASC','relevance'=>'b.created_at DESC'][$sort]??'b.created_at DESC';$q=$p->prepare('SELECT b.*,c.name category,COALESCE(AVG(r.rating),0) rating,COUNT(DISTINCT r.id) reviews,COUNT(DISTINCT f.user_id) favorites,'.$distance.' FROM businesses b JOIN categories c ON c.id=b.category_id LEFT JOIN reviews r ON r.business_id=b.id AND r.status="visible" LEFT JOIN favorites f ON f.business_id=b.id WHERE '.implode(' AND ',$w).' GROUP BY b.id ORDER BY '.$order);$q->execute($v);return $q->fetchAll();}
function page_head(string $title,string $content):never{$u=user();$f=take_flash();$active=$_GET['page']??'home';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> | Davao Local</title><link rel="stylesheet" href="style.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,600;9..144,700&display=swap" rel="stylesheet"></head><body><header class="site-header"><div class="nav-container"><a class="brand" href="index.php" aria-label="Davao Local home"><span class="brand-mark">D</span><span>Davao <b>Local</b></span></a><button class="nav-toggle" type="button" aria-label="Toggle navigation" aria-expanded="false" aria-controls="site-navigation"><span></span><span></span><span></span></button><nav id="site-navigation" aria-label="Primary navigation"><a class="<?=$active==='directory'?'active':''?>" href="?page=directory">Directory</a><a class="<?=$active==='map'?'active':''?>" href="?page=map">Map</a><?php if($u):?><a class="<?=$active==='dashboard'?'active':''?>" href="?page=dashboard">Dashboard</a><a href="notifications.php">Notifications</a><a class="nav-logout" href="?action=logout">Log out</a><?php else:?><a class="<?=$active==='login'?'active':''?>" href="?page=login">Log in</a><a class="nav-cta" href="?page=register">Join us</a><?php endif?></nav></div></header><?php if($f):?><div class="flash <?=e($f[1])?>"><?=e($f[0])?></div><?php endif?><main><?=$content?></main><footer>© <?=date('Y')?> Davao Local Directory <span>Find local. Support local.</span></footer></body></html><?php exit;}
function card(PDO $p,array $b):void{$open=business_open_now($p,(int)$b['id']);$services=array_slice(array_column(services($p,(int)$b['id']),'name'),0,3);?><article class="business-card"><?php if($b['logo_path']):?><img class="card-logo" src="<?=e($b['logo_path'])?>" alt="<?=e($b['name'])?> logo"><?php else:?><div class="card-icon"><?=e(strtoupper($b['name'][0]))?></div><?php endif?><div class="card-content"><div class="card-top"><span class="pill"><?=e($b['category'])?></span><?php if($b['is_verified']):?><small class="verified">✓ Verified</small><?php endif?></div><h3><?=e($b['name'])?></h3><p><?=e(mb_strimwidth($b['description']??'',0,115,'…'))?></p><div class="details"><span>📍 <?=e($b['barangay']?:$b['city'])?></span><span>⭐ <?=number_format((float)$b['rating'],1)?> (<?=$b['reviews']?>)</span><span class="directory-status <?=$open?'is-open':'is-closed'?>">● <?=$open?'Open now':'Closed'?></span><?php if($b['distance_km']!==null):?><span>📍 <?=number_format((float)$b['distance_km'],1)?> km away</span><?php endif?></div><?php if($services):?><p class="services"><b>Services:</b> <?=e(implode(', ',$services))?></p><?php endif?><div class="card-actions"><a class="button light" href="?page=business&id=<?=$b['id']?>">View business</a><?php if(is_role('customer')):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="favorite"><input type="hidden" name="business_id" value="<?=$b['id']?>"><button class="link-button" aria-label="Save <?=e($b['name'])?>">♡ Save</button></form><?php endif?></div></div></article><?php }
if(($_GET['action']??'')==='logout'){session_destroy();session_start();flash('Logged out.');go('index.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';
if($a==='register'){$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$role=$_POST['role']??'customer';if(!$email||!trim($_POST['name']??'')||strlen($_POST['password']??'')<8||!in_array($role,['customer','owner'],true)){flash('Complete valid details; password needs 8 characters.','error');go('?page=register');}try{$pdo->prepare('INSERT INTO users(role_id,name,email,password_hash) VALUES(?,?,?,?)')->execute([$role==='owner'?2:1,mb_strimwidth(trim($_POST['name']),0,100,''),$email,password_hash($_POST['password'],PASSWORD_DEFAULT)]);flash('Account created. Please log in.');}catch(PDOException){flash('Email already exists.','error');}go('?page=login');}
if($a==='login'){$q=$pdo->prepare('SELECT u.id,u.name,u.email,u.password_hash,r.name role,u.status FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=?');$q->execute([trim($_POST['email']??'')]);$x=$q->fetch();if($x&&$x['status']==='active'&&password_verify($_POST['password']??'',$x['password_hash'])){unset($x['password_hash'],$x['status']);$_SESSION['user']=$x;$pdo->prepare('UPDATE users SET last_login=NOW() WHERE id=?')->execute([$x['id']]);go('?page=dashboard');}flash('Incorrect email or password.','error');go('?page=login');}
if(!logged_in()){flash('Please log in first.','error');go('?page=login');}
if($a==='create'&&is_role('owner')){$need=['name','category_id','contact_phone','address'];foreach($need as $field)if(!trim($_POST[$field]??'')){flash('Complete all required fields.','error');go('?page=business-form');}$pdo->prepare('INSERT INTO businesses(owner_id,category_id,name,description,contact_phone,contact_email,address,barangay,district,city,latitude,longitude) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([user()['id'],(int)$_POST['category_id'],mb_strimwidth(trim($_POST['name']),0,150,''),trim($_POST['description']??''),trim($_POST['contact_phone']),filter_var($_POST['contact_email']??'',FILTER_VALIDATE_EMAIL)?:null,trim($_POST['address']),trim($_POST['barangay']??''),trim($_POST['district']??''),'Davao City',$_POST['latitude']!==''?$_POST['latitude']:null,$_POST['longitude']!==''?$_POST['longitude']:null]);$bid=(int)$pdo->lastInsertId();foreach(array_filter(array_map('trim',explode(',',$_POST['services']??''))) as $service){$pdo->prepare('INSERT IGNORE INTO services(name) VALUES(?)')->execute([$service]);$q=$pdo->prepare('SELECT id FROM services WHERE name=?');$q->execute([$service]);$pdo->prepare('INSERT IGNORE INTO business_services(business_id,service_id) VALUES(?,?)')->execute([$bid,$q->fetchColumn()]);}audit($pdo,user()['id'],'Business created','Business #'.$bid);flash('Listing submitted for approval.');go('owner.php');}
if($a==='review'&&is_role('customer')){$id=(int)$_POST['business_id'];$text=mb_strimwidth(trim($_POST['comment']??''),0,3000,'');$q=$pdo->prepare('SELECT owner_id FROM businesses WHERE id=? AND status="approved"');$q->execute([$id]);$owner=(int)$q->fetchColumn();if(!$owner||!$text){flash('Write a review first.','error');go('?page=business&id='.$id);}$pdo->prepare('INSERT INTO reviews(business_id,user_id,rating,comment)VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment)')->execute([$id,user()['id'],max(1,min(5,(int)$_POST['rating'])),$text]);notify_user($pdo,$owner,'You received a new customer review.','owner_reviews.php','review');go('?page=business&id='.$id);}
if($a==='review_delete'&&is_role('customer')){$pdo->prepare('DELETE FROM reviews WHERE id=? AND user_id=?')->execute([(int)$_POST['review_id'],user()['id']]);flash('Review deleted.');go('?page=business&id='.(int)$_POST['business_id']);}
if($a==='review_report'&&is_role('customer')){$review=(int)$_POST['review_id'];$reason=mb_strimwidth(trim($_POST['reason']??''),0,255,'');if($reason){$pdo->prepare('INSERT INTO review_reports(review_id,user_id,reason) VALUES(?,?,?) ON DUPLICATE KEY UPDATE reason=VALUES(reason),status="pending"')->execute([$review,user()['id'],$reason]);flash('Review report submitted.');}go('?page=business&id='.(int)$_POST['business_id']);}
if($a==='favorite'&&is_role('customer')){$id=(int)$_POST['business_id'];$pdo->prepare('INSERT IGNORE INTO favorites(user_id,business_id) VALUES(?,?)')->execute([user()['id'],$id]);go('?page=business&id='.$id);}
if($a==='inquiry'&&is_role('customer')){$id=(int)$_POST['business_id'];$sub=mb_strimwidth(trim($_POST['subject']??''),0,150,'');$msg=mb_strimwidth(trim($_POST['message']??''),0,3000,'');$q=$pdo->prepare('SELECT owner_id FROM businesses WHERE id=? AND status="approved"');$q->execute([$id]);$owner=(int)$q->fetchColumn();if(!$owner||!$sub||!$msg){flash('Complete the inquiry.','error');go('?page=business&id='.$id);}$pdo->prepare('INSERT INTO inquiries(business_id,user_id,subject,message)VALUES(?,?,?,?)')->execute([$id,user()['id'],$sub,$msg]);notify_user($pdo,$owner,'You have a new business inquiry.','owner.php','inquiry');go('?page=business&id='.$id);}}
if($page==='home'){$rows=array_slice(list_businesses($pdo),0,4);ob_start();?><section class="hero compact"><div class="hero-copy"><p class="eyebrow">DAVAO CITY SMALL BUSINESS DIRECTORY</p><h1>Discover local businesses <em>in Davao.</em></h1><p class="hero-text">Find trusted businesses and everyday services close to home.</p><form class="quick-search"><input type="hidden" name="page" value="directory"><label class="home-search-field"><span aria-hidden="true">⌕</span><input name="q" aria-label="Search business or service" placeholder="Search a business or service"></label><button class="button coral">Search <span aria-hidden="true">→</span></button></form><a class="hero-directory-link" href="?page=directory">Browse the full directory <span aria-hidden="true">→</span></a></div></section><section class="directory"><div class="section-title"><div><p class="eyebrow">DAVAO LOCAL DIRECTORY</p><h2>Support businesses<br>close to home.</h2></div><a class="button dark" href="?page=directory">Browse directory <span aria-hidden="true">→</span></a></div><div class="cards"><?php foreach($rows as $b)card($pdo,$b);?></div></section><?php page_head('Davao Local',ob_get_clean());}
if($page==='directory'){$rows=list_businesses($pdo);$active=[];$labels=['q'=>'Search: ','area'=>'Area: ','rating'=>'','verified'=>'Verified','open'=>'Open now','contact'=>'Has contact','map'=>'Has map','services'=>'Has services','price_min'=>'Min ₱','price_max'=>'Max ₱'];foreach($labels as $key=>$prefix){if(($_GET[$key]??'')!==''&&($_GET[$key]??'')!=='0')$active[$key]=$key==='rating'?$_GET[$key].'+ stars':$prefix.($_GET[$key]==='1'?'':$_GET[$key]);}$categoryId=(int)($_GET['category']??0);if($categoryId){foreach(cats($pdo) as $c)if($c['id']===$categoryId)$active['category']=$c['name'];}ob_start();?><section class="directory page"><p class="eyebrow">LOCAL BUSINESS DIRECTORY</p><h1>Find what you need.</h1><form class="directory-filters" id="directory-filters"><input type="hidden" name="page" value="directory"><input type="hidden" name="lat" value="<?=e($_GET['lat']??'')?>"><input type="hidden" name="lng" value="<?=e($_GET['lng']??'')?>"><label class="filter-search"><span>Search</span><span class="search-input">⌕ <input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Business name or service"></span></label><label><span>Category</span><select name="category"><option value="">All categories</option><?php foreach(cats($pdo) as $c):?><option value="<?=$c['id']?>" <?=($categoryId===$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></label><label><span>Area / barangay</span><input name="area" value="<?=e($_GET['area']??'')?>" placeholder="Any area"></label><label><span>Rating</span><select name="rating"><option value="">Any rating</option><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>" <?=((int)($_GET['rating']??0)===$i)?'selected':''?>><?=$i?> stars+</option><?php endfor?></select></label><div class="filter-options"><label><input type="checkbox" name="verified" value="1" <?=($_GET['verified']??'')==='1'?'checked':''?>> Verified only</label><label><input type="checkbox" name="open" value="1" <?=($_GET['open']??'')==='1'?'checked':''?>> Open now</label><label><input type="checkbox" name="contact" value="1" <?=($_GET['contact']??'')==='1'?'checked':''?>> Has contact</label><label><input type="checkbox" name="map" value="1" <?=($_GET['map']??'')==='1'?'checked':''?>> Has map</label><label><input type="checkbox" name="services" value="1" <?=($_GET['services']??'')==='1'?'checked':''?>> Available services</label></div><label><span>Price range</span><span class="price-range"><input type="number" min="0" step=".01" name="price_min" value="<?=e($_GET['price_min']??'')?>" placeholder="Min"><input type="number" min="0" step=".01" name="price_max" value="<?=e($_GET['price_max']??'')?>" placeholder="Max"></span></label><label><span>Sort by</span><select name="sort"><option value="relevance">Relevance</option><option value="rating" <?=($_GET['sort']??'')==='rating'?'selected':''?>>Highest rated</option><option value="reviews" <?=($_GET['sort']??'')==='reviews'?'selected':''?>>Most reviewed</option><option value="favorites" <?=($_GET['sort']??'')==='favorites'?'selected':''?>>Most favorited</option><option value="nearest" <?=($_GET['sort']??'')==='nearest'?'selected':''?>>Nearest</option><option value="newest" <?=($_GET['sort']??'')==='newest'?'selected':''?>>Newest</option><option value="name_az" <?=($_GET['sort']??'')==='name_az'?'selected':''?>>A–Z</option><option value="name_za" <?=($_GET['sort']??'')==='name_za'?'selected':''?>>Z–A</option></select></label><div class="filter-actions"><button class="button coral">Apply filters</button><button type="button" class="button light" data-clear-filters>Clear filters</button><button type="button" class="near-me" data-near-me>📍 Near me</button></div></form><?php if($active):?><div class="active-filters"><span>Showing results for:</span><?php foreach($active as $key=>$label):?><a href="?<?=e(http_build_query(array_diff_key($_GET,[$key=>true])))?>" class="filter-chip"><?=e($label)?> <b aria-label="Remove filter">×</b></a><?php endforeach?><a class="clear-all" href="?page=directory">Clear all</a></div><?php endif?><div class="result-summary"><p><b><?=count($rows)?> businesses found</b></p><?php if($categoryId&&isset($active['category'])):?><p>Showing results for: <?=e($active['category'])?></p><?php endif?></div><div class="cards"><?php foreach($rows as $b)card($pdo,$b);if(!$rows):?><div class="empty"><h2>No businesses found</h2><p>Try changing or clearing your filters.</p><a class="button light" href="?page=directory">Clear filters</a></div><?php endif?></div></section><?php page_head('Directory',ob_get_clean());}
if($page==='login'||$page==='register'){$r=$page==='register';ob_start();?><section class="auth"><div><p class="eyebrow"><?=$r?'JOIN DAVAO LOCAL':'WELCOME BACK'?></p><h1><?=$r?'Create an account.':'Log in to Davao Local.'?></h1></div><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="<?=$r?'register':'login'?>"><?php if($r):?><label>Name<input required maxlength="100" name="name"></label><label>Account type<select name="role"><option value="customer">Customer</option><option value="owner">Business owner</option></select></label><?php endif?><label>Email<input required type="email" name="email"></label><label>Password<input required minlength="8" type="password" name="password"></label><button class="button dark"><?=$r?'Create account':'Log in'?></button></form></section><?php page_head($r?'Register':'Login',ob_get_clean());}
if($page==='business-form'){if(!is_role('owner')){flash('Business owner access required.','error');go('?page=login');}ob_start();?><section class="form-page"><p class="eyebrow">BUSINESS OWNER</p><h1>Create a business profile</h1><form method="post" class="registration-form wide"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create"><div class="form-grid"><label>Business name *<input required maxlength="150" name="name"></label><label>Category *<select required name="category_id"><option value="">Choose category</option><?php foreach(cats($pdo) as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach?></select></label><label>Contact number *<input required name="contact_phone"></label><label>Email<input type="email" name="contact_email"></label><label>Address *<input required name="address"></label><label>Barangay<input name="barangay"></label><label>District<input name="district"></label><label>Latitude<input type="number" step="any" name="latitude"></label><label>Longitude<input type="number" step="any" name="longitude"></label></div><label>Services (comma-separated)<input name="services"></label><label>Description<textarea name="description"></textarea></label><button class="button dark">Submit for approval</button></form></section><?php page_head('Create business',ob_get_clean());}
if($page==='business'){$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT b.*,c.name category,COALESCE(AVG(r.rating),0) rating,COUNT(r.id) reviews FROM businesses b JOIN categories c ON c.id=b.category_id LEFT JOIN reviews r ON r.business_id=b.id AND r.status="visible" WHERE b.id=? AND b.status="approved" GROUP BY b.id');$q->execute([$id]);$b=$q->fetch();if(!$b)page_head('Not found','<section class="directory page"><h1>Business not found.</h1></section>');$pdo->prepare('INSERT INTO business_views(business_id,user_id) VALUES(?,?)')->execute([$id,user()['id']??null]);$q=$pdo->prepare('SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.business_id=? AND r.status="visible" ORDER BY r.created_at DESC');$q->execute([$id]);$reviews=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM business_hours WHERE business_id=?');$q->execute([$id]);$hours=array_column($q->fetchAll(),null,'day_of_week');$q=$pdo->prepare('SELECT * FROM business_images WHERE business_id=? ORDER BY created_at DESC');$q->execute([$id]);$images=$q->fetchAll();$sv=services($pdo,$id);ob_start();?><section class="profile"><p class="eyebrow"><?=e($b['category'])?></p><div class="profile-head"><?php if($b['logo_path']):?><img class="profile-logo" src="<?=e($b['logo_path'])?>" alt=""><?php endif?><div><h1><?=e($b['name'])?><?php if($b['is_verified']):?> <small class="verified">✓ Verified business</small><?php endif?></h1><p><?=e($b['description'])?></p><span class="rating">★ <?=number_format((float)$b['rating'],1)?> <small>(<?=$b['reviews']?> reviews)</small></span><p><b><?=business_open_now($pdo,$id)?'OPEN NOW':'CLOSED'?></b></p></div><div class="actions"><?php if(is_role('customer')):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="favorite"><input type="hidden" name="business_id" value="<?=$id?>"><button class="button dark">♡ Save</button></form><?php endif?><a class="button coral" target="_blank" href="https://www.openstreetmap.org/?mlat=<?=e($b['latitude'])?>&mlon=<?=e($b['longitude'])?>">Directions</a></div></div><div class="profile-grid"><div><?php if($images):?><article class="info-box"><h2>Gallery</h2><div class="gallery-grid"><?php foreach($images as $im):?><figure><img src="<?=e($im['image_path'])?>" alt="<?=e($im['caption'])?>"><figcaption><?=e($im['caption'])?></figcaption></figure><?php endforeach?></div></article><?php endif?><article class="info-box"><h2>Services</h2><?php foreach($sv as $s):?><p><b><?=e($s['name'])?></b><?= $s['price']!==null?' · ₱'.number_format((float)$s['price'],2):''?><br><?=e($s['description'])?></p><?php endforeach?></article><article class="info-box"><h2>Reviews</h2><?php foreach($reviews as $r):?><div class="review"><b><?=e($r['name'])?></b> <span class="rating">★ <?=$r['rating']?></span> <small><?=e(date('M j, Y',strtotime($r['created_at'])))?></small><p><?=e($r['comment'])?></p><?php if($r['response']):?><p><b>Owner reply:</b> <?=e($r['response'])?></p><?php endif?><?php if(is_role('customer')&&$r['user_id']==user()['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="review_delete"><input type="hidden" name="review_id" value="<?=$r['id']?>"><input type="hidden" name="business_id" value="<?=$id?>"><button class="danger">Delete my review</button></form><?php endif?></div><?php endforeach?><?php if(is_role('customer')):?><form method="post" class="mini-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="review"><input type="hidden" name="business_id" value="<?=$id?>"><select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>"><?=$i?> stars</option><?php endfor?></select><textarea required maxlength="3000" name="comment" placeholder="Write or update your review"></textarea><button class="button coral">Save review</button></form><?php endif?></article></div><aside class="contact-box"><h2>Contact information</h2><p>☎ <?=e($b['contact_phone'])?></p><p>✉ <?=e($b['contact_email'])?></p><p>⌖ <?=e($b['address'])?>, <?=e($b['barangay'])?>, <?=e($b['city'])?></p><h3>Weekly schedule</h3><?php foreach(['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'] as $d=>$name):$h=$hours[$d]??null;?><p><?=e($name)?>: <?=(!$h||$h['is_closed'])?'Closed':e(substr($h['opens'],0,5).'–'.substr($h['closes'],0,5))?></p><?php endforeach?><?php if(is_role('customer')):?><hr><h3>Send inquiry</h3><form method="post" class="mini-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="inquiry"><input type="hidden" name="business_id" value="<?=$id?>"><input required maxlength="150" name="subject" placeholder="Subject"><textarea required maxlength="3000" name="message" placeholder="Your message"></textarea><button class="button dark">Send inquiry</button></form><hr><h3>Book appointment</h3><form action="appointments.php" method="post" class="mini-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="book"><input type="hidden" name="business_id" value="<?=$id?>"><select name="service_id"><option value="">Select a service</option><?php foreach($sv as $s):?><option value="<?=$s['service_id']?>"><?=e($s['name'])?></option><?php endforeach?></select><input required type="datetime-local" name="appointment_at" min="<?=date('Y-m-d\\TH:i')?>"><textarea name="notes" maxlength="2000" placeholder="Optional notes"></textarea><button class="button coral">Request appointment</button></form><hr><h3>Report business</h3><form action="reports.php" method="post" class="mini-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="business_id" value="<?=$id?>"><select required name="reason"><option value="">Choose reason</option><option value="fake_business">Fake business</option><option value="wrong_information">Wrong information</option><option value="inappropriate_content">Inappropriate content</option><option value="duplicate_listing">Duplicate listing</option><option value="closed_business">Closed business</option><option value="other">Other</option></select><textarea name="details" maxlength="3000" placeholder="Optional details"></textarea><button class="link-button">Submit report</button></form><?php endif?></aside></div></section><?php page_head($b['name'],ob_get_clean());}
